:root {
  --bg: #1a1a2e;
  --surface: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #f0f0f0;
  --text-dim: #a0a0b0;
  --known: #4ecca3;
  --border: 4px solid var(--accent);
  --pixel-shadow: 4px 4px 0 var(--accent);
  --font: 'Courier New', Courier, monospace;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.app {
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

.title {
  font-size: 28px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 3px 3px 0 var(--surface);
}

.known-count {
  font-size: 16px;
  color: var(--text-dim);
  letter-spacing: 1px;
}

.card {
  width: 100%;
  min-height: 220px;
  background: var(--surface);
  border: var(--border);
  box-shadow: var(--pixel-shadow);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  padding: 24px;
  transition: transform 0.08s, box-shadow 0.08s;
  outline: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.card:focus-visible {
  outline: 4px solid var(--accent-hover);
  outline-offset: 4px;
}

.card:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.card-face {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.card-label {
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 3px;
  color: var(--accent);
}

.card-text {
  font-size: 24px;
  line-height: 1.4;
  word-break: break-word;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  width: 100%;
}

.btn {
  flex: 1 1 auto;
  min-width: 100px;
  padding: 14px 18px;
  font-family: var(--font);
  font-size: 16px;
  font-weight: bold;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--text);
  background: var(--surface);
  border: var(--border);
  box-shadow: var(--pixel-shadow);
  cursor: pointer;
  transition: transform 0.08s, box-shadow 0.08s, background 0.08s;
  -webkit-tap-highlight-color: transparent;
}

.btn:hover {
  background: var(--accent);
  color: var(--bg);
}

.btn:focus-visible {
  outline: 4px solid var(--accent-hover);
  outline-offset: 4px;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.btn.got-it {
  border-color: var(--known);
  box-shadow: 4px 4px 0 var(--known);
}

.btn.got-it:hover {
  background: var(--known);
  color: var(--bg);
}

.btn.got-it.known {
  background: var(--known);
  color: var(--bg);
  opacity: 0.7;
  cursor: default;
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
  box-shadow: var(--pixel-shadow);
}

@media (max-width: 400px) {
  .title { font-size: 22px; }
  .card { min-height: 180px; padding: 16px; }
  .card-text { font-size: 20px; }
  .btn { padding: 12px 10px; font-size: 14px; min-width: 80px; }
}

(function() {
  'use strict';

  var cards = [
    { word: 'Ephemeral', meaning: 'Lasting for a very short time.' },
    { word: 'Serendipity', meaning: 'Finding something good without looking for it.' },
    { word: 'Resilient', meaning: 'Able to recover quickly from difficulties.' },
    { word: 'Luminous', meaning: 'Full of or shedding light; bright.' },
    { word: 'Pragmatic', meaning: 'Dealing with things sensibly and realistically.' }
  ];

  var currentIndex = 0;
  var showingMeaning = false;
  var known = cards.map(function() { return false; });

  var cardEl = document.getElementById('card');
  var cardLabel = document.getElementById('cardLabel');
  var cardText = document.getElementById('cardText');
  var prevBtn = document.getElementById('prevBtn');
  var nextBtn = document.getElementById('nextBtn');
  var gotItBtn = document.getElementById('gotItBtn');
  var knownCount = document.getElementById('knownCount');

  function render() {
    var card = cards[currentIndex];
    cardLabel.textContent = showingMeaning ? 'Meaning' : 'Word';
    cardText.textContent = showingMeaning ? card.meaning : card.word;
    cardEl.setAttribute('aria-label', 'Flashcard: ' + (showingMeaning ? 'meaning' : 'word') + '. Click or press Enter to flip.');

    knownCount.textContent = 'Known: ' + known.filter(Boolean).length + ' / ' + cards.length;

    prevBtn.disabled = currentIndex === 0;
    nextBtn.disabled = currentIndex === cards.length - 1;

    if (known[currentIndex]) {
      gotItBtn.textContent = 'Known ✓';
      gotItBtn.classList.add('known');
      gotItBtn.disabled = true;
    } else {
      gotItBtn.textContent = 'Got it!';
      gotItBtn.classList.remove('known');
      gotItBtn.disabled = false;
    }
  }

  function flip() {
    showingMeaning = !showingMeaning;
    render();
  }

  function goPrev() {
    if (currentIndex > 0) {
      currentIndex--;
      showingMeaning = false;
      render();
    }
  }

  function goNext() {
    if (currentIndex < cards.length - 1) {
      currentIndex++;
      showingMeaning = false;
      render();
    }
  }

  function markKnown() {
    if (!known[currentIndex]) {
      known[currentIndex] = true;
      render();
    }
  }

  cardEl.addEventListener('click', flip);
  cardEl.addEventListener('keydown', function(e) {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      flip();
    }
  });

  prevBtn.addEventListener('click', goPrev);
  nextBtn.addEventListener('click', goNext);
  gotItBtn.addEventListener('click', markKnown);

  render();
})();
